        onSearch={setSearchQuery}
      />
      <div className="app-body">
        <Sidebar
          groups={CONTENT_GROUPS}
          activeId={activeId}
          onSelect={handleSelectGroup}
          open={sidebarOpen}
        />
        <main className="app-main">
                  {searchQuery ? (
                    <SearchView query={searchQuery} onClose={() => setSearchQuery('')} />
                  ) : isAdmin ? (
